    results = table.fetchone()
    if not results:
        table = conn.execute('select * from systems where lower(name) = ?', (search,))
        results = table.fetchone()
    if results:
        keys = tuple(i[0] for i in table.description)
        return '\n'.join(f'{key.replace("_", " ").title()}: {field}'
