    let part
    while ((part = await parts()) != null) {
      if (part.file) {
        yield part
      }
    }
  }

  async function * getMultipartIterator (options) {
    const parts = this[kMultipartHandler](options)

    let part
    while ((part = await parts()) != null) {
      yield part
    }
  }

  done()
}

function receiveMessage(event) {
    if (!isOriginAllowed(event.origin)) {
      return;
    }

    var data;
    try {
      data = JSON.parse(event.data);
    } catch (err) {
    }
    if (data && data.namespace === MESSAGE_NAMESPACE) {
      if (data.action === 'set') {
        setData(data.id, data.key, data.value, event.origin);
      } else if (data.action === 'get') {
        getData(data.id, data.key, event.origin);
      } else if (data.action === 'remove') {
        removeData(data.id, data.key, event.origin);
      } else if (data.action === 'key') {
        getKey(data.id, data.key, event.origin);
      } else if (data.action === 'clear') {
        clear(data.id, event.origin);
      }
    }
  }

function chart_legend_options(item){
  if(item.data('series').length == 1) return {show: false};
  var options = item.data('legend-options');
  switch (options)
  {
    case "external":
      return {show: true,
        noColumns:4,
        container:"#legendContainer",
        labelFormatter: function(label, series) {
          return '<a rel="twipsy" data-original-title="' + __('Details') + '" href="' + series.href + '">' + label + '</a>';
        }
      };
    case "hide":
      return {show: false};
    default:
      return {show: true, margin: [0, -60]};
  }
}

function appendline(session, text)
	{
		if(chats[session] && chats[session].content)
		{
			text = AjaxLife.Utils.LinkURLs(text.escapeHTML());
			var line = Ext.get(document.createElement('div'));
			line.addClass(["agentmessage","chatline"]);
			var timestamp = Ext.get(document.createElement('span'));
			timestamp.addClass("chattimestamp");
			var time = new Date();
			timestamp.dom.appendChild(document.createTextNode("["+time.getHours()+":"+((time.getMinutes()<10)?("0"+time.getMinutes()):time.getMinutes())+"]"));
			line.dom.appendChild(timestamp.dom);
			line.dom.appendChild(document.createTextNode(" "));
			var span = document.createElement('span');
			span.innerHTML = text;
			line.dom.appendChild(span);
			chats[session].content.dom.appendChild(line.dom);
			chats[session].content.dom.scrollTop = chats[session].content.dom.scrollHeight;
		}
		else
		{
			AjaxLife.Widgets.Ext.msg("Warning","Instant message with unknown ID {0}:<br />{1}",session,text);
		}
	}

function dockerContainerInspect(containerID, payload) {
  return new Promise((resolve) => {
    process.nextTick(() => {
      containerID = containerID || '';
      if (typeof containerID !== 'string') {
        resolve();
      }
      const containerIdSanitized = (util.isPrototypePolluted() ? '' : util.sanitizeShellString(containerID, true)).trim();
      if (containerIdSanitized) {

        if (!_docker_socket) {
          _docker_socket = new DockerSocket();
        }

        _docker_socket.getInspect(containerIdSanitized.trim(), data => {
          try {
            resolve({
              id: payload.Id,
              name: payload.Name,
              image: payload.Image,
              imageID: payload.ImageID,
              command: payload.Command,
              created: payload.Created,
              started: data.State && data.State.StartedAt ? Math.round(new Date(data.State.StartedAt).getTime() / 1000) : 0,
              finished: data.State && data.State.FinishedAt && !data.State.FinishedAt.startsWith('0001-01-01') ? Math.round(new Date(data.State.FinishedAt).getTime() / 1000) : 0,
              createdAt: data.Created ? data.Created : '',
              startedAt: data.State && data.State.StartedAt ? data.State.StartedAt : '',
              finishedAt: data.State && data.State.FinishedAt && !data.State.FinishedAt.startsWith('0001-01-01') ? data.State.FinishedAt : '',
              state: payload.State,
              restartCount: data.RestartCount || 0,
              platform: data.Platform || '',
              driver: data.Driver || '',
              ports: payload.Ports,
              mounts: payload.Mounts,
            });
          } catch (err) {
            resolve();
          }
        });
      } else {
        resolve();
      }
    });
  });
}

