doDownloadTo(out) {
    inMeteor(this.wrapCallback(function () {
      const safe = ssrfSafeLookupOrProxy(globalDb, this.url);

      let bytesExpected = undefined;
      let bytesReceived = 0;
      const hasher = Crypto.createHash("sha256");
      let done = false;
      const updateDownloadProgress = _.throttle(this.wrapCallback(() => {
        if (!done) {
          if (bytesExpected) {
            this.updateProgress("download", bytesReceived / bytesExpected);
          } else {
            this.updateProgress("download", bytesReceived);
          }
        }
      }), 500);

      const request = safe.proxy
          ? Request.get(this.url, { proxy: safe.proxy })
          : Request.get(safe.url, {
              headers: { host: safe.host },
              servername: safe.host.split(":")[0],
            });

      request.on("response", this.wrapCallback((response) => {
        if ("content-length" in response.headers) {
          bytesExpected = parseInt(response.headers["content-length"]);
        }
      }));

      request.on("data", this.wrapCallback((chunk) => {
        hasher.update(chunk);
        out.write(chunk);
        bytesReceived += chunk.length;
        updateDownloadProgress();
      }));

      request.on("end", this.wrapCallback(() => {
        out.done();

        if (hasher.digest("hex").slice(0, 32) !== this.packageId) {
          throw new Error("Package hash did not match.");
        }

        done = true;
        delete this.downloadRequest;

        this.updateProgress("unpack");
        out.saveAs(this.packageId).then(this.wrapCallback((info) => {
          this.appId = info.appId;
          this.authorPgpKeyFingerprint = info.authorPgpKeyFingerprint;
          this.done(info.manifest);
        }), this.wrapCallback((err) => {
          throw err;
        }));
      }));

      request.on("error", this.wrapCallback((err) => { throw err; }));

      this.downloadRequest = request;
    }));
  }

function uploadFile(file) {
				if (file.size> attachmentMaxSize) {
					var message = "!!Upload should be less than " + Math.round(attachmentMaxSize/1024/1024) + " Mb!!";
					onedev.server.markdown.updateUploadMessage($input, message);
				} else {
					var xhr = new XMLHttpRequest();
					var val = $input.val();
					var i=1;
					var message = "[Uploading file...]";
					while (val.indexOf(message) != -1) {
						message = "[Uploading file" + (++i) + "...]";
					}

					xhr.replaceMessage = message;
					if ($input.range().length == 0) {
						$input.caret(message);
					} else {
						$input.range(message);
						$input.caret($input.caret()+message.length);
					}

					xhr.onload = function() {
						var response = xhr.responseText;
						var index = response.indexOf("<?xml");
						if (index != -1)
							response = response.substring(0, index);
						if (xhr.status == 200) {
							callback("insertUrl", response, xhr.replaceMessage);
						} else {
							onedev.server.markdown.updateUploadMessage($input,
									"!!" + response + "!!", xhr.replaceMessage);
						}
					};
					xhr.onerror = function() {
						onedev.server.markdown.updateUploadMessage($input,
								"!!Unable to connect to server!!", xhr.replaceMessage);
					};

					xhr.open("POST", attachmentUploadUrl, true);
					xhr.setRequestHeader("File-Name", encodeURIComponent(file.name));
					xhr.setRequestHeader("Wicket-Ajax", "true");
					xhr.setRequestHeader("Wicket-Ajax-BaseURL", Wicket.Ajax.baseUrl);

					xhr.send(file);
				}
			}

